/bin/bash -lc "find / -type f \\( -name pvpython -o -name paraview -o -name 'ttkPersistenceDiagram*' \\) 2>/dev/null | head -50; python - <<'PY'
try:
 import paraview
 print('paraview',paraview.__file__)
except Exception as e: print('no paraview', e)
try:
 import vtk
 print('vtk',vtk.VTK_VERSION)
except Exception as e: print('no vtk',e)
PY"

