/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/fracture.vti'])
for f in [TTKPersistenceDiagram(Input=r), TTKTopologicalSimplification(Domain=r), TTKMorseSmaleComplex(Input=r)]:
 print('\\n',f.GetXMLName())
 for p in f.ListProperties():
  try: print(p, '=', getattr(f,p))
  except: pass
PY"

